:root {
  --bg: #1e1e2e;
  --card: #2a2a3c;
  --accent: #f5a623;
  --text: #e0e0e8;
  --muted: #9a9ab0;
  --cell: #3a3a50;
  --cell-alt: #323246;
  --robot: #4cd964;
  --robot-eye: #1e1e2e;
  --danger: #ff6b6b;
  --radius: 12px;
  --focus-ring: 0 0 0 3px var(--accent);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.5px;
}

.subtitle {
  font-size: 0.9rem;
  color: var(--muted);
  margin-top: -12px;
}

.readout {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.readout-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 100px;
}

.readout-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.readout-value {
  font-size: 1.1rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 2px;
  background: var(--bg);
  border-radius: 8px;
  padding: 2px;
  aspect-ratio: 1;
  width: 100%;
}

.cell {
  background: var(--cell);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.cell:nth-child(even) {
  background: var(--cell-alt);
}

.robot {
  width: 70%;
  height: 70%;
  background: var(--robot);
  border-radius: 6px;
  position: relative;
  transition: transform 0.15s ease;
  box-shadow: 0 0 8px rgba(76, 217, 100, 0.5);
}

.robot::before,
.robot::after {
  content: '';
  position: absolute;
  width: 18%;
  height: 18%;
  background: var(--robot-eye);
  border-radius: 50%;
  top: 30%;
}

.robot::before {
  left: 20%;
}

.robot::after {
  right: 20%;
}

/* Direction indicator: a small notch on the robot */
.robot[data-dir="right"] {
  transform: rotate(0deg);
}
.robot[data-dir="down"] {
  transform: rotate(90deg);
}
.robot[data-dir="left"] {
  transform: rotate(180deg);
}
.robot[data-dir="up"] {
  transform: rotate(-90deg);
}

.robot[data-dir="right"]::before { left: 20%; }
.robot[data-dir="right"]::after { right: 20%; }

.status {
  min-height: 1.4em;
  font-size: 0.9rem;
  color: var(--danger);
  text-align: center;
  font-weight: 500;
}

.controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 16px;
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  background: var(--cell);
  color: var(--text);
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  min-height: 48px;
}

.btn:hover {
  background: #4a4a64;
  border-color: var(--muted);
}

.btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.btn:active {
  transform: scale(0.96);
  background: #5a5a78;
}

.btn.primary {
  background: var(--accent);
  color: var(--bg);
  grid-column: 1 / -1;
}

.btn.primary:hover {
  background: #ffb84d;
  border-color: transparent;
}

.btn.primary:active {
  background: #e0951a;
}

.btn.secondary {
  background: transparent;
  border-color: var(--muted);
  color: var(--muted);
}

.btn.secondary:hover {
  background: var(--cell);
  color: var(--text);
  border-color: var(--text);
}

.btn.secondary:active {
  background: #4a4a64;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    gap: 16px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .controls {
    grid-template-columns: 1fr;
  }
  .btn.primary {
    grid-column: auto;
  }
}

(function () {
  'use strict';

  const SIZE = 5;
  const DIRECTIONS = ['up', 'right', 'down', 'left'];
  const DIR_LABELS = { up: 'Up', right: 'Right', down: 'Down', left: 'Left' };

  const state = {
    row: 0,
    col: 0,
    dirIndex: 1 // right
  };

  const gridEl = document.getElementById('grid');
  const positionEl = document.getElementById('position');
  const directionEl = document.getElementById('direction');
  const statusEl = document.getElementById('status');

  // Build grid cells once
  const cells = [];
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.setAttribute('role', 'gridcell');
      cell.setAttribute('aria-rowindex', String(r + 1));
      cell.setAttribute('aria-colindex', String(c + 1));
      gridEl.appendChild(cell);
      cells.push(cell);
    }
  }

  const robotEl = document.createElement('div');
  robotEl.className = 'robot';
  robotEl.setAttribute('aria-hidden', 'true');

  function getCell(row, col) {
    return cells[row * SIZE + col];
  }

  function render() {
    // Remove robot from previous cell
    if (robotEl.parentNode) {
      robotEl.parentNode.removeChild(robotEl);
    }
    const cell = getCell(state.row, state.col);
    cell.appendChild(robotEl);
    robotEl.dataset.dir = DIRECTIONS[state.dirIndex];

    positionEl.textContent = '(' + (state.row + 1) + ', ' + (state.col + 1) + ')';
    directionEl.textContent = DIR_LABELS[DIRECTIONS[state.dirIndex]];
  }

  function clearStatus() {
    statusEl.textContent = '';
  }

  function forward() {
    clearStatus();
    let nr = state.row;
    let nc = state.col;
    const dir = DIRECTIONS[state.dirIndex];
    if (dir === 'up') nr--;
    else if (dir === 'down') nr++;
    else if (dir === 'left') nc--;
    else if (dir === 'right') nc++;

    if (nr < 0 || nr >= SIZE || nc < 0 || nc >= SIZE) {
      statusEl.textContent = 'Blocked! The robot cannot leave the grid.';
      return;
    }
    state.row = nr;
    state.col = nc;
    render();
  }

  function turnLeft() {
    clearStatus();
    state.dirIndex = (state.dirIndex + 3) % 4;
    render();
  }

  function turnRight() {
    clearStatus();
    state.dirIndex = (state.dirIndex + 1) % 4;
    render();
  }

  function reset() {
    clearStatus();
    state.row = 0;
    state.col = 0;
    state.dirIndex = 1;
    render();
  }

  document.getElementById('btn-forward').addEventListener('click', forward);
  document.getElementById('btn-left').addEventListener('click', turnLeft);
  document.getElementById('btn-right').addEventListener('click', turnRight);
  document.getElementById('btn-reset').addEventListener('click', reset);

  render();
})();
